INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(124873, 'ruRU', '', 'Люди больше даже не узнают истинную инженю! Это так... трагично.', 24330),
(124874, 'ruRU', '', 'Ох, дорогууу-ушка, я так рада тебя видеть. Ты принёс розы?', 24330),
(124875, 'ruRU', '', 'Ты ожидал, что я назову тебя "мои красотки"? Может, устроить пару вихрей? Это называется *актёрская игра*, дорогуша.', 24330),
(124877, 'ruRU', '', 'В их смерти мы обретём искупление.', 24330),
(124883, 'ruRU', '', 'Угх! Он такой невыносимый! Вот болван.', 24330),
(124885, 'ruRU', '', 'Что ж, думаю, этот уже исчерпал свою полезность, не находишь?', 24330),
(124886, 'ruRU', '', 'Я отправлюсь обратно в Трещину Ужаса и сообщу остальным членам совета о нашем плане.', 24330),
(124894, 'ruRU', '', 'Арлуэль кладёт тёмно-фиолетовый цветок перед маленьким цветочным горшком.', 24330),
(124902, 'ruRU', '', '<Должно быть, это остатки покойной помощницы Грукса.>$B$B<Ты замечаешь что-то, едва выступающее из пепла. Должно быть, это перфокарта, которую она пыталась вернуть!>', 24330),
(124904, 'ruRU', '', 'Они не видели моего приближения. Один клинок, бьющий из теней, остаётся незамеченным, и одна трещина в их защите открывается.', 24330),
(124911, 'ruRU', '', 'sdf', 24330),
(124914, 'ruRU', '', 'Прошу, не задерживайся здесь долго, $ct $n. Это ужасное место истощает мою волю с каждым вдохом.', 24330),
(124956, 'ruRU', '', 'Ну, чего тебе надо?', 24330),
(124982, 'ruRU', '', 'Ты ЧТО?!', 24330),
(125000, 'ruRU', '', 'Нам нужно немедленно доставить тебя в Гномреган!', 24330),
(125001, 'ruRU', '', 'Калибровка гипернапряжённых флуктуаторов... настройка микроускорителя...', 24330),
(125002, 'ruRU', '', 'Я отправлю тебя глубоко в город. В аттенюаторе осталось сока только на один раз, так что нужно сделать всё правильно!', 24330),
(125004, 'ruRU', '', 'Успех!', 24330),
(125005, 'ruRU', '', 'Если у телепорта закончится сок, нам понадобится |Hitem:143653:0:0:0:0:0:0:0:90:0|h[Переполненный краеугольный камень]|h, чтобы его перезапустить. Вставай на платформу, как только будешь готов!', 24330),
(125012, 'ruRU', '', '|TInterface\\Icons\\inv_misc_monsterhorn_03.blp:20|t %s появляется далеко от Хелии!', 24330),
(125051, 'ruRU', '', 'Сэр, у нас есть причины полагать, что за всем этим стоит Термаплаг. И у него в арсенале есть какая-то ракета!', 24330),
(125092, 'ruRU', '', 'Архимаги, используйте свою силу, чтобы убедить этих двоих объединиться!', 24330),
(125094, 'ruRU', '', 'Сумеречная Стража грозна. Нам понадобится каждый способный боец, если мы хотим выполнить нашу задачу.', 24330),
(125095, 'ruRU', '', 'У этих эльфов крови довольно грозная магия. Будем надеяться, что её хватит, чтобы противостоять могуществу Ночного Колодца.', 24330),
(125099, 'ruRU', '', 'Я видел, как Часовые тренировались в стрельбе по мишеням в своём лагере. Они уж точно умеют стрелять...$b$bМы никогда по-настоящему не принимали лук. В конце концов, кому нужны такие примитивные орудия, когда можно создать саму ткань мира, чтобы она метала снаряды за тебя?', 24330),
(125100, 'ruRU', '', 'Какие глупцы... Вы действительно думали, что сможете уйти так легко?', 24330),
(125101, 'ruRU', '', 'Позвольте показать вам милосердие Клятвенника Пустоты!', 24330),
(125102, 'ruRU', '', 'Мой повелитель... я подвёл тебя...', 24330),
(125132, 'ruRU', '', 'Не прекращай музыку!', 24330),
(125134, 'ruRU', '', 'Мяу.', 24330),
(125135, 'ruRU', '', 'Талисра, надеюсь, это сообщение найдёт тебя в добром здравии. Я только что вернулась с экстренного совета касательно сил Орды и Альянса, скопившихся за пределами Сурамара.', 24330),
(125137, 'ruRU', '', 'Элизанда назначила нового Первого Чародея: ужасную женщину по имени Андарис. Вместе они работают над массивным заклинанием, чтобы прорвать осаду.', 24330),
(125140, 'ruRU', '', 'Атака на главные ворота — плохая идея, но может быть другой путь. Андарис направила своих чародеев в Святилище Порядка.', 24330),
(125145, 'ruRU', '', 'Мяу-мяу.', 24330),
(125146, 'ruRU', '', 'Мяу-мяу-мяу.', 24330),
(125149, 'ruRU', '', 'Похоже, есть какой-то пролом, что проходит под Ночным Колодцем и ведёт прямо во дворец! Они пытаются его заделать, но я уверена, ты сможешь найти способ—', 24330),
(125150, 'ruRU', '', 'Кто-то идёт... Кто ты?! П-подожди! Отпусти меня! Как ты смеешь! Ты знаешь, кто я?!', 24330),
(125151, 'ruRU', '', 'Хорошо, давай, активируй его... Я отойду на... безопасное для наблюдения расстояние', 24330),
(125152, 'ruRU', '', 'Следуй за мной наверх, там мы сможем активировать этот куб, вдали от любопытных покупателей...', 24330),
(125168, 'ruRU', '', 'Левия... да, я её знаю. Она останавливается здесь время от времени. В последний раз это было пару дней назад.\n\nМагия тени — опасная штука, именно поэтому Кирин-Тор не любит её в городе, но то, чем она балуется, намного хуже обычных дел. Хотел бы я, чтобы она хотя бы вела свои делишки за пределами города.\n\nМожешь подняться наверх и проверить, не оставила ли она что-нибудь.', 24330);
